import java.util.*;
import java.util.regex.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine().trim());
        Set<String> reserved = new HashSet<>(Arrays.asList("class", "public", "static", "void", "int", "if", "else", "return"));
        Pattern idPat = Pattern.compile("^[a-zA-Z_][a-zA-Z0-9_]{0,29}$");
        Pattern emailPat = Pattern.compile("^[a-zA-Z0-9](?:[a-zA-Z0-9_-]|\\.(?=[a-zA-Z0-9_-]))*@[a-zA-Z0-9-]+\\.[a-zA-Z]{2,6}$");
        for (int i = 0; i < n; i++) {
            String[] parts = sc.nextLine().trim().split("\\s+");
            String type = parts[0], tok = parts[1];
            boolean ok = false;
            if (type.equals("ID")) {
                ok = idPat.matcher(tok).matches() && !reserved.contains(tok);
            } else if (type.equals("EMAIL")) {
                ok = emailPat.matcher(tok).matches();
            }
            System.out.println(ok ? "VALID" : "INVALID");
        }
    }
}
